class Container(Element):
    """An element with children, declared in a ``with`` block.

    Modifiers chained before the block or applied after it change the container.
    """

    __slots__ = ()

    def __init__(self, view: View) -> None:
        super().__init__(view)
        view._begin(self)

    def __enter__(self) -> Container:
        return self

    def __exit__(self, *exception: object) -> None:
        self._serial = self._view._end_container(self)


def version() -> int:
    """The version of the loaded library, packed as major << 22 | minor << 12 | patch.

    Thread-safe.
    """
    return _native.rk_version()


def last_error() -> str:
    """Describes the last failure on the calling thread.

    Thread-safe.

    Returns:
        Valid until the next failing call on this thread; empty if nothing failed.
    """
    return _runtime.read(_native.rk_last_error())


def open_url(url: str) -> None:
    """Opens a web address in the desktop's browser, or another URL in the program that handles its
    scheme, such as mailto: in the mail program.

    Thread-safe.

    Args:
        url: An absolute URL such as https://example.org.

    Raises:
        Error: With the failing status.
    """
    _check(_native.rk_open_url(_runtime.text(url)))


def open_file(path: str) -> None:
    """Opens a file or folder in the desktop's default program for it.

    Thread-safe.

    Args:
        path: Absolute, or relative to the working directory.

    Raises:
        Error: With the failing status.
    """
    _check(_native.rk_open_file(_runtime.text(path)))


def text_width(text: str, size: float) -> float:
    """How wide one line of text is when :meth:`View.text` draws it with :meth:`Element.text_size`
    and no other text styling, in logical pixels.

    Args:
        size: The text size in logical pixels; above 0.
    """
    return _native.rk_text_width(_runtime.text(text), size)


